-- Editable presentation defaults; retain existing custom palette fields.
update public.site_settings set value = '{"secondary": "#F0BD78", "soft": "#E5EEE5", "surface": "#FFFFFF", "muted": "#526566", "accentText": "#FFFFFF", "secondaryText": "#302719", "darkBackground": "#0D191B", "darkText": "#F1F5EF", "darkAccent": "#85D8CB", "darkSecondary": "#EFC28C", "darkSurface": "#162629", "darkSoft": "#213735", "darkMuted": "#AEC2BC", "darkAccentText": "#102423", "darkSecondaryText": "#302719", "heroOverlay": "#081D23", "heroText": "#FFFFFF", "successColor": "#206347", "errorColor": "#AA3441", "darkSuccessColor": "#9AE4BF", "darkErrorColor": "#FFABB5", "navCtaLabel": "Plan your trip", "navCtaHref": "/contact"}'::jsonb || value where slug='site-config';
update public.site_settings set value = value || jsonb_build_object('accent',case when value->>'accent'='#476A63' then '#0B655F' else value->>'accent' end,'background',case when value->>'background'='#FFFFFF' then '#FAFCFA' else value->>'background' end,'textColor',case when value->>'textColor'='#1D1D1F' then '#142E31' else value->>'textColor' end), updated_at=now() where slug='site-config';
update public.site_settings set value=jsonb_set(value,'{ui}','{"theme": "Appearance", "light": "Light", "dark": "Dark", "system": "System", "scrollCue": "A little more to discover", "videoPause": "Pause background video", "videoPlay": "Play background video"}'::jsonb || coalesce(value->'ui','{}'::jsonb)) where slug='site-config';
update public.page_sections set content=content || '{"eyebrow": "AN ISLAND. A THOUSAND POSSIBILITIES.", "heading": "Sri Lanka.\nCloser to wonder.", "body": "Misty hills. Ancient stories. Endless blue.\nFind a journey that moves at your pace.", "cta_label": "Explore the journeys", "cta_href": "/tours", "secondary_label": "Plan your trip", "secondary_href": "/contact", "scroll_label": "A little more to discover"}'::jsonb where page_id=(select id from public.pages where slug='home') and type='hero' and content->>'heading' like '[PLACEHOLDER]%';
insert into public.page_sections(slug,page_id,type,content,published,sort_order,is_placeholder) select 'home-featured-journeys',id,'featured_tours','{"heading": "An island, your way.", "body": "From cultural landmarks to winding railways and quiet stretches of coast. Start with a little inspiration.", "limit": 3, "tour_ids": [], "cta_label": "View all journeys", "cta_href": "/tours"}'::jsonb,true,10,true from public.pages where slug='home' on conflict(slug) do nothing;
insert into public.page_sections(slug,page_id,type,content,published,sort_order,is_placeholder) select 'home-island-map',id,'map_preview','{"heading": "Find your own path.", "body": "Explore the places, connect the dots, and imagine where your journey could take you.", "cta_label": "Explore the island", "cta_href": "/map"}'::jsonb,true,20,true from public.pages where slug='home' on conflict(slug) do nothing;
insert into public.page_sections(slug,page_id,type,content,published,sort_order,is_placeholder) select 'home-inquiry-band',id,'call_to_action','{"heading": "Where will your story begin?", "body": "Tell us what you have in mind. Let\u2019s start with a conversation.", "cta_label": "Plan your trip", "cta_href": "/contact"}'::jsonb,true,30,true from public.pages where slug='home' on conflict(slug) do nothing;
